  let viewers=1284;let displayedViewers=viewers;function animateViewers(target){const start=displayedViewers,started=performance.now(),duration=850;function frame(now){const progress=Math.min(1,(now-started)/duration),eased=progress<.5?2*progress*progress:1-Math.pow(-2*progress+2,2)/2;displayedViewers=Math.round(start+(target-start)*eased);document.getElementById('viewer-count').textContent=bn(displayedViewers.toLocaleString('en-US'));if(progress<1)requestAnimationFrame(frame)}requestAnimationFrame(frame)}setInterval(()=>{const delta=Math.floor(Math.random()*19)-8;viewers=Math.max(1090,Math.min(1680,viewers+delta));animateViewers(viewers)},4200);
  let seconds=300;const timer=document.getElementById('countdown'),hourHand=document.querySelector('.watch-hand--hour'),minuteHand=document.querySelector('.watch-hand--minute');function updateTimer(){const elapsed=300-seconds;if(timer)timer.textContent=bn(String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0'));if(hourHand)hourHand.style.transform=`rotate(${elapsed*1.2}deg)`;if(minuteHand)minuteHand.style.transform=`rotate(${elapsed*6}deg)`}updateTimer();setInterval(()=>{seconds=seconds>0?seconds-1:300;updateTimer()},1000);
